/* prog48_sorted_linked_list.c
 * Re‑implementation of the original program’s observable behaviour:
 *   * reads up to 64 signed decimal numbers from the command line,
 *   * stores them in descending order,
 *   * prints the numbers separated by a single space,
 *   * prints a trailing newline,
 *   * prints "EMPTY" (followed by a newline) when no numbers are given.
 *
 * The implementation follows the logic discovered in the decompiled
 * binary but is written in clear, idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>

#define MAX_VALUES 64

int main(int argc, char *argv[])
{
    /* No numbers supplied – match the original behaviour. */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    long values[MAX_VALUES];
    int count = 0;                 /* number of stored values */

    /* Process each command‑line argument, stop after MAX_VALUES. */
    for (int i = 1; i < argc && count < MAX_VALUES; ++i) {
        char *endptr = NULL;
        long v = strtol(argv[i], &endptr, 10);   /* decimal conversion */

        /* Insert v into the array keeping it sorted in descending order. */
        int pos = count;                         /* position where v will go */
        while (pos > 0 && values[pos - 1] < v) {
            values[pos] = values[pos - 1];       /* shift larger elements right */
            --pos;
        }
        values[pos] = v;
        ++count;
    }

    /* Output the sorted list. */
    for (int i = 0; i < count; ++i) {
        printf("%ld", values[i]);
        if (i + 1 < count)
            putchar(' ');
    }
    putchar('\n');

    return 0;
}
